let
    Demo = Binary.Decompress(Binary.FromText("", BinaryEncoding.Base64), Compression.Deflate),
    Source = if DataMode = "Demo" then Demo else if DataMode = "Folder" then File.Contents(DataFolder & "/Cash.csv") else error "DataMode must be Demo or Folder",
    Parsed = Csv.Document(Source, [Delimiter=",", Encoding=65001, QuoteStyle=QuoteStyle.Csv]),
    Headers = Table.PromoteHeaders(Parsed, [PromoteAllScalars=true]),
    Typed = Table.TransformColumnTypes(Headers, {{"CashID", type text}, {"DepartmentID", type text}, {"Date", type date}, {"Category", type text}, {"CashMovement", Currency.Type}}, "en-US")
in
    Typed
